CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS players(
 player_id uuid primary key, account_id uuid not null, character_id uuid not null unique,
 character_name varchar(32) not null, gender varchar(16) not null, face varchar(128), hair varchar(128),
 appearance_json jsonb not null default '{}'::jsonb, level integer not null default 1 check(level>=1), xp bigint not null default 0 check(xp>=0),
 rank varchar(64) not null default 'Unranked', profile_json jsonb not null default '{}'::jsonb,
 version bigint not null default 1 check(version>0), created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
CREATE INDEX IF NOT EXISTS ix_players_account on players(account_id);
CREATE TABLE IF NOT EXISTS player_progression(player_id uuid primary key references players(player_id) on delete cascade,skill_points integer not null default 0 check(skill_points>=0),attributes_json jsonb not null default '{}',stats_json jsonb not null default '{}',version bigint not null default 1,updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS skills(player_id uuid not null references players(player_id) on delete cascade,skill_id varchar(128) not null,level integer not null default 1 check(level>0),progress bigint not null default 0 check(progress>=0),unlocked_at timestamptz not null default now(),version bigint not null default 1,primary key(player_id,skill_id));
CREATE TABLE IF NOT EXISTS inventory_items(item_instance_id uuid primary key,player_id uuid not null references players(player_id) on delete cascade,item_id varchar(128) not null,quantity bigint not null check(quantity>0),durability numeric(12,3),metadata_json jsonb not null default '{}',version bigint not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
CREATE INDEX IF NOT EXISTS ix_inventory_player on inventory_items(player_id);
CREATE TABLE IF NOT EXISTS equipment(player_id uuid not null references players(player_id) on delete cascade,slot varchar(64) not null,item_instance_id uuid references inventory_items(item_instance_id),version bigint not null default 1,updated_at timestamptz not null default now(),primary key(player_id,slot));
CREATE TABLE IF NOT EXISTS economy_balances(player_id uuid not null references players(player_id) on delete cascade,currency varchar(64) not null,balance numeric(30,0) not null check(balance>=0),version bigint not null default 1,updated_at timestamptz not null default now(),primary key(player_id,currency));
CREATE TABLE IF NOT EXISTS economy_ledger(ledger_id uuid primary key default gen_random_uuid(),player_id uuid not null references players(player_id),currency varchar(64) not null,delta numeric(30,0) not null,reason varchar(128) not null,idempotency_key varchar(128) not null unique,balance_after numeric(30,0) not null,created_at timestamptz not null default now());
CREATE INDEX IF NOT EXISTS ix_economy_player on economy_ledger(player_id,created_at desc);
CREATE TABLE IF NOT EXISTS trades(trade_id uuid primary key,initiator uuid not null references players(player_id),recipient uuid not null references players(player_id),state varchar(32) not null,offer_json jsonb not null default '{}',version bigint not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS purchases(purchase_id uuid primary key,player_id uuid not null references players(player_id),provider varchar(64) not null,external_reference varchar(256) not null unique,state varchar(32) not null,amount numeric(30,0) not null,metadata_json jsonb not null default '{}',created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS refunds(refund_id uuid primary key,purchase_id uuid not null references purchases(purchase_id),external_reference varchar(256) unique,state varchar(32) not null,amount numeric(30,0) not null,created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS rewards(reward_id uuid primary key,player_id uuid not null references players(player_id),source_type varchar(64) not null,source_id varchar(128) not null,reward_json jsonb not null,claimed_at timestamptz,created_at timestamptz not null default now(),unique(player_id,source_type,source_id));
CREATE TABLE IF NOT EXISTS quests(player_id uuid not null references players(player_id) on delete cascade,quest_id varchar(128) not null,state varchar(32) not null,objectives_json jsonb not null default '{}',reward_json jsonb not null default '{}',version bigint not null default 1,updated_at timestamptz not null default now(),primary key(player_id,quest_id));
CREATE TABLE IF NOT EXISTS discoveries(player_id uuid not null references players(player_id) on delete cascade,discovery_type varchar(64) not null,discovery_id varchar(128) not null,metadata_json jsonb not null default '{}',discovered_at timestamptz not null default now(),primary key(player_id,discovery_type,discovery_id));
CREATE TABLE IF NOT EXISTS achievements(player_id uuid not null references players(player_id) on delete cascade,achievement_id varchar(128) not null,progress bigint not null default 0,completed_at timestamptz,primary key(player_id,achievement_id));
CREATE TABLE IF NOT EXISTS player_settings(player_id uuid primary key references players(player_id) on delete cascade,settings_json jsonb not null default '{}',hud_json jsonb not null default '{}',controls_json jsonb not null default '{}',localization varchar(16) not null default 'en',audio_json jsonb not null default '{}',graphics_json jsonb not null default '{}',version bigint not null default 1,updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS social_relationships(player_id uuid not null references players(player_id) on delete cascade,other_player_id uuid not null references players(player_id),relationship varchar(32) not null,created_at timestamptz not null default now(),primary key(player_id,other_player_id,relationship));
CREATE TABLE IF NOT EXISTS parties(party_id uuid primary key,leader_id uuid not null references players(player_id),state varchar(32) not null,version bigint not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS party_members(party_id uuid not null references parties(party_id) on delete cascade,player_id uuid not null references players(player_id),role varchar(32) not null,joined_at timestamptz not null default now(),primary key(party_id,player_id));
CREATE TABLE IF NOT EXISTS mail(mail_id uuid primary key,player_id uuid not null references players(player_id),sender_id uuid references players(player_id),subject varchar(200) not null,body text not null,payload_json jsonb not null default '{}',read_at timestamptz,expires_at timestamptz,created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS reputation(player_id uuid primary key references players(player_id) on delete cascade,reputation bigint not null default 0,pk_level integer not null default 0 check(pk_level>=0),bounty numeric(30,0) not null default 0 check(bounty>=0),wanted boolean not null default false,version bigint not null default 1,updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS matches(match_id uuid primary key,mode varchar(64) not null,state varchar(32) not null,started_at timestamptz,ended_at timestamptz,metadata_json jsonb not null default '{}');
CREATE TABLE IF NOT EXISTS match_participants(match_id uuid not null references matches(match_id) on delete cascade,player_id uuid not null references players(player_id),team integer,result varchar(32),statistics_json jsonb not null default '{}',reward_json jsonb not null default '{}',rank_delta integer not null default 0,disconnect_state varchar(32),reconnect_token_hash varchar(128),primary key(match_id,player_id));
CREATE TABLE IF NOT EXISTS cities(city_id uuid primary key,kingdom_id varchar(128) not null,name varchar(128) not null,destroyed boolean not null default false,updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS rifts(rift_id uuid primary key,location_json jsonb not null,kingdom_id varchar(128),city_id uuid references cities(city_id),state varchar(32) not null check(state in('Active','Escalated','Merging','Engulfed','Cleared','Failed')),timers_json jsonb not null default '{}',attempts integer not null default 0,escalation integer not null default 0,version bigint not null default 1,updated_at timestamptz not null default now(),created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS rift_participants(rift_id uuid not null references rifts(rift_id) on delete cascade,player_id uuid not null references players(player_id),joined_at timestamptz not null default now(),result varchar(32),reward_json jsonb not null default '{}',primary key(rift_id,player_id));
CREATE TABLE IF NOT EXISTS supreme_ruins(ruin_id uuid primary key,god_id varchar(64) not null,state varchar(32) not null check(state in('Locked','Available','InChallenge','Claimed','Completed')),challenger_player_id uuid references players(player_id),challenge_started_at timestamptz,version bigint not null default 1,inheritance_owner_id uuid references players(player_id),completed_at timestamptz,updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS ruin_divine_creatures(ruin_id uuid not null references supreme_ruins(ruin_id) on delete cascade,creature_id varchar(128) not null,killed boolean not null default false,killed_at timestamptz,primary key(ruin_id,creature_id));
CREATE TABLE IF NOT EXISTS inheritance_history(history_id uuid primary key default gen_random_uuid(),ruin_id uuid not null references supreme_ruins(ruin_id),god_id varchar(64) not null,player_id uuid not null references players(player_id),action varchar(32) not null,created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS idempotency_keys(idempotency_key varchar(128) primary key,player_id uuid not null references players(player_id),new_version bigint not null,result_json jsonb not null,created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS audit_log(audit_id uuid primary key default gen_random_uuid(),actor_id varchar(256) not null,player_id uuid,category varchar(64) not null,action varchar(128) not null,correlation_id varchar(128),created_at timestamptz not null default now());
CREATE INDEX IF NOT EXISTS ix_audit_player on audit_log(player_id,created_at desc);
